    greetings = (
        (range(0, 12), "Good Morning"),
        (range(12, 17), "Good Afternoon"),
        (range(17, 24), "Good Evening")
    );
    return `list(filter(lambda (x: Any) { (hour in x[0]); }, greetings))[0][1];
}

