"""
    Given two vectors, returns the manhatten distance between them
    Requires that they are the same dimension

    :param first: a vector
    :param second: a vector

    :return: the distance as a double
    """
def manhatten_distance(first: Any, second: Any) -> object {
    if (len(first) != len(second)) {
        raise Exception("These vectors must be the same size");
    }
    return sum([abs((x - y)) for (x, y) in zip(first, second)]);
}

"""
    Calculate the number of characters that differ
    between two strings of identical length. Returns
    1 if lengths do not match.

    """
def string_distance(s1: Any, s2: Any) -> object {
    if (len(s1) != len(s2)) {
        return 1;
    }
    diff_count = 0;
    for (c1, c2) in zip(s1, s2) {
        if (c1 != c2) {
            diff_count += 1;
        }
    }
    return diff_count;
}

